function toast(message){ui.toast.textContent=message;ui.toast.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>ui.toast.classList.remove('show'),2200)}
function initAudio(){if(audio)return;audio=new(window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),filter=audio.createBiquadFilter();engineGain=audio.createGain();osc.type='sawtooth';osc.frequency.value=42;filter.type='lowpass';filter.frequency.value=130;engineGain.gain.value=0;osc.connect(filter).connect(engineGain).connect(audio.destination);osc.start()}
function beep(freq=740,duration=.12){if(!state.sound)return;initAudio();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
function powered(){return state.battery||state.groundPower||state.apuGen||state.engines.some(n=>n>55)}
function toggleSystem(name,button){state[name]=!state[name];button.classList.toggle('on',state[name]);button.textContent=button.textContent.replace(/ ON| OFF/g,'')+(state[name]?' ON':' OFF');if(name==='apuMaster'&&!state.apuMaster){state.apuRunning=false;state.apuGen=false}refreshChecklist();beep(520,.05)}
function startAPU(){if(!state.battery||!state.apuMaster||!state.fuelPumps){toast('APU START 需要 BATTERY、APU MASTER 和 FUEL PUMPS');return}if(state.apuRunning)return;toast('APU 正在启动…');const b=$('[data-action="apuStart"]');b.classList.add('start');setTimeout(()=>{state.apuRunning=true;b.classList.remove('start');b.classList.add('on');b.textContent='APU RUNNING';toast('APU 可用');beep(880,.18);refreshChecklist()},3200)}
function startEngine(index){if(!state.apuRunning||!state.bleed||!state.fuelPumps){toast('发动机启动需要 APU RUNNING、APU BLEED 和 FUEL PUMPS');return}if(state.engineStarting[index]||state.engines[index]>50)return;state.engineStarting[index]=true;toast(`ENGINE ${index+1} START`);const timer=setInterval(()=>{state.engines[index]=Math.min(64,state.engines[index]+3);if(state.engines[index]>=60){clearInterval(timer);state.engineStarting[index]=false;state.engines[index]=60;toast(`ENGINE ${index+1} STABLE`);beep(940,.13);refreshChecklist()}},140)}
function setReady(){Object.assign(state,{battery:true,groundPower:false,apuMaster:true,apuRunning:true,apuGen:true,fuelPumps:true,hydraulics:true,packs:true,bleed:true,beacon:true,engines:[60,60],ready:true});$$('[data-switch]').forEach(b=>{const n=b.dataset.switch;b.classList.toggle('on',!!state[n])});$('[data-action="apuStart"]').classList.add('on');$('[data-action="apuStart"]').textContent='APU RUNNING';refreshChecklist()}
function refreshChecklist(){const values={battery:state.battery,ground:state.groundPower||state.apuGen||state.engines.some(n=>n>55),apu:state.apuRunning,fuel:state.fuelPumps,engines:state.engines.every(n=>n>55),hydraulics:state.hydraulics};$$('.check').forEach(row=>{const ok=values[row.dataset.check];row.classList.toggle('done',ok);row.querySelector('b').textContent=ok?'ON':'OFF'})}
function begin(quick){initAudio();state.running=true;ui.start.classList.add('hidden');if(quick)setReady();toast(quick?'飞机已在跑道就绪':'从顶板开始：BATTERY → GROUND POWER → APU');}

const tutorialSteps=[
  {title:'打开顶板',text:'737 的冷舱启动从头顶面板开始。这里负责电源、燃油、引气、液压和灯光。',target:'#overheadBtn',done:()=>ui.overhead.classList.contains('open'),prepare:()=>ui.overhead.classList.remove('open')},
  {title:'接通电瓶',text:'点击 BATTERY。电瓶为基础控制和备用系统供电，是冷舱启动的第一步。',target:'[data-switch="battery"]',done:()=>state.battery},
  {title:'接通地面电源',text:'点击 GROUND POWER，让飞机在发动机未启动时获得稳定交流电。仪表随后会点亮。',target:'[data-switch="groundPower"]',done:()=>state.groundPower},
  {title:'开启燃油泵',text:'点击 FUEL PUMPS。APU 和发动机启动前必须保证燃油供应。',target:'[data-switch="fuelPumps"]',done:()=>state.fuelPumps},
  {title:'启动 APU',text:'先打开 APU MASTER，再点击 APU START。等待约 3 秒，按钮显示 APU RUNNING。',target:'[data-switch="apuMaster"]',done:()=>state.apuRunning},
  {title:'建立引气',text:'APU 运转后点击 APU BLEED。引气提供发动机启动所需的压缩空气。',target:'[data-switch="bleed"]',done:()=>state.bleed},
  {title:'启动双发',text:'依次点击 ENGINE 1 和 ENGINE 2，等待两台发动机稳定到 60%。',target:'[data-action="startEng1"]',done:()=>state.engines.every(n=>n>55)},
  {title:'接通液压',text:'点击 HYD PUMPS。没有液压，主要飞行操纵面无法正常工作。',target:'[data-switch="hydraulics"]',done:()=>state.hydraulics},
  {title:'设置起飞襟翼',text:'把右下角 FLAPS 拉到 5。襟翼增加低速升力，缩短起飞距离。',target:'#flaps',done:()=>state.flaps>=2,prepare:()=>ui.overhead.classList.remove('open')},
  {title:'起飞',text:'把 THRUST 推到 TO/GA。速度超过约 118 节后按住 W 抬头；正上升后按 G 收起落架。',target:'#throttle',done:()=>state.airborne&&state.altitude>100}
];
function clearTutorialTarget(){$$('.tutorial-target').forEach(e=>e.classList.remove('tutorial-target'))}
function showTutorialStep(){clearTutorialTarget();const step=tutorialSteps[tutorialIndex];if(!step){finishTutorial();return}step.prepare?.();$('#tutorialProgress').textContent=`冷舱启动教学 ${tutorialIndex+1} / ${tutorialSteps.length}`;$('#tutorialTitle').textContent=step.title;$('#tutorialText').textContent=step.text;$('#tutorialBack').disabled=tutorialIndex===0;$('#tutorialNext').textContent=tutorialIndex===tutorialSteps.length-1?'完成':'下一步';const target=$(step.target);target?.classList.add('tutorial-target');$('#tutorialHint').textContent=step.done()?'已完成 ✓':'等待你完成操作…'}
function startTutorial(){if(!state.running)begin(false);tutorialActive=true;tutorialIndex=0;$('#tutorial').classList.remove('hidden');document.body.classList.remove('view-external');state.external=false;showTutorialStep()}
function finishTutorial(){tutorialActive=false;clearTutorialTarget();$('#tutorial').classList.add('hidden');toast('冷舱启动教学完成！');localStorage.setItem('b738-tutorial-complete','1')}
function monitorTutorial(){if(!tutorialActive)return;const step=tutorialSteps[tutorialIndex];if(step?.done()){$('#tutorialHint').textContent='已完成 ✓';$('#tutorialNext').classList.add('active')}}

$$('[data-switch]').forEach(b=>b.addEventListener('click',()=>toggleSystem(b.dataset.switch,b)));$('[data-action="apuStart"]').onclick=startAPU;$('[data-action="startEng1"]').onclick=()=>startEngine(0);$('[data-action="startEng2"]').onclick=()=>startEngine(1);
$('#tutorialStart').onclick=startTutorial;$('#coldStart').onclick=()=>begin(false);$('#quickStart').onclick=()=>begin(true);$('#overheadBtn').onclick=()=>ui.overhead.classList.toggle('open');$('#cduBtn').onclick=()=>ui.cdu.classList.toggle('open');
$('#tutorialBtn').onclick=startTutorial;$('#tutorialClose').onclick=()=>{tutorialActive=false;clearTutorialTarget();$('#tutorial').classList.add('hidden')};$('#tutorialBack').onclick=()=>{tutorialIndex=Math.max(0,tutorialIndex-1);showTutorialStep()};$('#tutorialNext').onclick=()=>{const step=tutorialSteps[tutorialIndex];if(!step.done()){toast('请先完成当前教学操作');return}tutorialIndex++;showTutorialStep()};
$('#viewBtn').onclick=()=>{state.external=!state.external;document.body.classList.toggle('view-external',state.external);$('#viewBtn').textContent=state.external?'驾驶舱视角':'外部视角'};
ui.sound.onclick=()=>{state.sound=!state.sound;ui.sound.textContent=`声音 ${state.sound?'ON':'OFF'}`;ui.sound.classList.toggle('active',state.sound);if(engineGain&&!state.sound)engineGain.gain.value=0};
ui.throttle.oninput=()=>{state.throttle=+ui.throttle.value;$('#throttleVal').textContent=state.throttle>90?'TO/GA':state.throttle+'%'};ui.flaps.oninput=()=>{state.flaps=+ui.flaps.value;$('#flapsVal').textContent=state.flaps?['','1','5','15','30','40'][state.flaps]:'UP'};ui.speedbrake.oninput=()=>{state.speedbrake=+ui.speedbrake.value;$('#speedbrakeVal').textContent=state.speedbrake>75?'UP':state.speedbrake?'ARMED':'DOWN'};ui.gear.onclick=()=>{state.gearDown=!state.gearDown;ui.gear.classList.toggle('down',state.gearDown);ui.gear.innerHTML=`GEAR<br>${state.gearDown?'DOWN':'UP'}`;beep(430,.12)};
$$('[data-ap]').forEach(b=>b.onclick=()=>{const n=b.dataset.ap;if(n==='ap'&&!state.engines.every(v=>v>50)){toast('CMD A 不可用：发动机未运行');return}state.ap[n]=!state.ap[n];b.classList.toggle('on',state.ap[n]);beep(state.ap[n]?900:480,.08)});
['mcpSpeed','mcpHeading','mcpAltitude'].forEach(id=>$('#'+id).onchange=()=>{const k=id.replace('mcp','').toLowerCase();state.targets[k]=+$('#'+id).value});
const waypointMap={PEK:[0,-2200],ANDAN:[600,-3800],OLNEX:[-500,-5600],SASAN:[0,-7600]};
$('#execRoute').onclick=()=>{const names=$('#route').value.toUpperCase().split(',').map(v=>v.trim()).filter(Boolean);state.route=names.map((name,i)=>({name,pos:waypointMap[name]||[(i%2?1:-1)*500,-2200-i*1600]}));state.activeLeg=0;$('#legs').textContent=`${$('#origin').value.toUpperCase()} → ${names.join(' → ')} → ${$('#destination').value.toUpperCase()}\nACTIVATE / EXECUTED`;state.ap.lnav=true;$('[data-ap="lnav"]').classList.add('on');toast('航路已执行，LNAV ARM');beep(1000,.12)};

addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='g')ui.gear.click();if(e.key.toLowerCase()==='v')$('#viewBtn').click();if(e.key.toLowerCase()==='f'){ui.flaps.value=Math.min(5,+ui.flaps.value+1);ui.flaps.oninput()}});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);

function flightPhysics(dt){const running=state.engines.reduce((a,b)=>a+b,0)/120;const n1=running*(22+state.throttle*.78);const drag=0.011*state.ias+state.flaps*1.1+(state.gearDown?3.2:0)+state.speedbrake*.045;let accel=n1*.082-drag-1.1;if(state.onGround&&state.ias<4&&state.throttle<8)accel=-state.ias;state.ias=Math.max(0,state.ias+accel*dt);
  let pitchInput=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),rollInput=(keys.a||keys.arrowleft?-1:0)+(keys.d||keys.arrowright?1:0),rudderInput=(keys.q?-1:0)+(keys.e?1:0);
  if(state.ap.ap){if(state.ap.heading||state.ap.lnav){let target=state.targets.heading;if(state.ap.lnav&&state.route.length){const leg=state.route[state.activeLeg],dx=leg.pos[0]-state.x,dz=leg.pos[1]-state.z;target=(Math.atan2(dx,-dz)*180/Math.PI+360)%360;if(Math.hypot(dx,dz)<240&&state.activeLeg<state.route.length-1)state.activeLeg++}let delta=((target-state.heading+540)%360)-180;rollInput=THREE.MathUtils.clamp(delta/22,-1,1)}if(state.ap.altitude||state.ap.vnav){const err=state.targets.altitude-state.altitude;pitchInput=THREE.MathUtils.clamp(err/1800-state.vs/3500,-.55,.75)}if(state.ap.at){const err=state.targets.speed-state.ias;state.throttle=THREE.MathUtils.clamp(state.throttle+err*.04*dt,0,100);ui.throttle.value=state.throttle}}
  state.roll+=((rollInput*28)-state.roll)*Math.min(1,dt*2.2);state.pitch+=((pitchInput*12)-state.pitch)*Math.min(1,dt*1.8);state.rudder+=(rudderInput-state.rudder)*Math.min(1,dt*2.5);document.documentElement.style.setProperty('--yoke-roll',`${state.roll*.8}deg`);
  const rotateRate=(state.roll*.11+state.rudder*2.5)*Math.min(1,state.ias/90);state.heading=(state.heading+rotateRate*dt+360)%360;const flapLift=state.flaps*1.3;const liftFactor=Math.max(0,(state.ias-105+flapLift*5)/80);state.vs=(state.pitch*155+flapLift*80-220+liftFactor*210)-(state.speedbrake*7);if(state.onGround){if(state.ias>118&&state.pitch>4){state.onGround=false;state.airborne=true;state.y=3.2;toast('POSITIVE RATE');beep(900,.1)}else{state.vs=0;state.altitude=0;state.y=2.8}}
  if(!state.onGround){state.altitude=Math.max(0,state.altitude+state.vs/60*dt);state.y=2.8+state.altitude*.018;if(state.altitude<=0){const safe=state.ias<155&&Math.abs(state.vs)<650&&state.gearDown;state.onGround=true;state.y=2.8;if(state.airborne){state.airborne=false;saved.cycles++;const landing=Math.round(Math.abs(state.vs));saved.bestLanding=saved.bestLanding?Math.min(saved.bestLanding,landing):landing;localStorage.setItem('b738-sim-records',JSON.stringify(saved));toast(safe?`着陆完成 · ${landing} ft/min`:'重着陆警告');beep(safe?620:250,safe?.18:.7)}}}
  const rad=state.heading*Math.PI/180,speedM=state.ias*.5144;state.x+=Math.sin(rad)*speedM*dt;state.z-=Math.cos(rad)*speedM*dt;state.flightSeconds+=dt;saved.hours+=dt/3600;if(Math.floor(state.flightSeconds)%30===0)localStorage.setItem('b738-sim-records',JSON.stringify(saved));aircraft.position.set(state.x,state.y,state.z);aircraft.rotation.set(state.pitch*Math.PI/180,rad,state.roll*-Math.PI/180);
  if(state.radioAlt<500&&!state.gearDown&&!state.onGround&&performance.now()-warningTimer>3000){toast('TOO LOW — GEAR');beep(260,.55);warningTimer=performance.now()}if(engineGain&&state.sound)engineGain.gain.value=running*(.015+state.throttle*.0005);
}

function fitCanvas(c){const dpr=Math.min(devicePixelRatio,2),w=c.clientWidth,h=c.clientHeight;if(c.width!==w*dpr||c.height!==h*dpr){c.width=w*dpr;c.height=h*dpr}const x=c.getContext('2d');x.setTransform(dpr,0,0,dpr,0,0);return{x,w,h}}
function drawPFD(){const{x,w,h}=fitCanvas(ui.pfd);x.clearRect(0,0,w,h);if(!powered()){x.fillStyle='#080909';x.fillRect(0,0,w,h);x.fillStyle='#ff8b25';x.font='12px Consolas';x.fillText('DISPLAY SOURCE',w/2-48,h/2);return}x.save();x.translate(w/2,h/2);x.rotate(-state.roll*Math.PI/180);const py=state.pitch*3;x.fillStyle='#1987bc';x.fillRect(-w,-h*2+py,w*2,h*2);x.fillStyle='#7d5032';x.fillRect(-w,py,w*2,h*2);x.strokeStyle='#fff';x.lineWidth=2;x.beginPath();x.moveTo(-w,py);x.lineTo(w,py);x.stroke();for(let p=-20;p<=20;p+=5){if(!p)continue;const yy=py-p*3;x.lineWidth=1;x.beginPath();x.moveTo(-20,yy);x.lineTo(20,yy);x.stroke();x.fillStyle='#fff';x.font='9px Consolas';x.fillText(Math.abs(p),24,yy+3)}x.restore();x.strokeStyle='#fff';x.lineWidth=3;x.beginPath();x.moveTo(w/2-28,h/2);x.lineTo(w/2-8,h/2);x.lineTo(w/2,h/2+7);x.lineTo(w/2+8,h/2);x.lineTo(w/2+28,h/2);x.stroke();x.fillStyle='#111d';x.fillRect(0,0,52,h);x.fillRect(w-59,0,59,h);x.fillStyle='#fff';x.font='bold 17px Consolas';x.fillText(Math.round(state.ias),9,h/2+5);x.fillText(Math.round(state.altitude),w-55,h/2+5);x.fillStyle='#71e77b';x.font='bold 11px Consolas';const modes=[state.ap.at?'MCP SPD':'',state.ap.lnav?'LNAV':state.ap.heading?'HDG SEL':'',state.ap.vnav?'VNAV PTH':state.ap.altitude?'ALT HOLD':''];x.fillText(modes.join('   '),8,14);x.fillStyle='#fff';x.font='10px Consolas';x.fillText(`V/S ${Math.round(state.vs)}`,w-70,h-10);x.fillText(`HDG ${String(Math.round(state.heading)).padStart(3,'0')}`,w/2-28,h-8)}
function drawND(){const{x,w,h}=fitCanvas(ui.nd);x.fillStyle='#020506';x.fillRect(0,0,w,h);if(!powered()){x.fillStyle='#ff8b25';x.font='12px Consolas';x.fillText('MAP',w/2-12,h/2);return}const cx=w/2,cy=h*.78,range=8000;x.strokeStyle='#31514f';x.lineWidth=1;for(const r of[45,85,125]){x.beginPath();x.arc(cx,cy,r,Math.PI,Math.PI*2);x.stroke()}x.strokeStyle='#fff';x.beginPath();x.moveTo(cx,cy-7);x.lineTo(cx-5,cy+7);x.lineTo(cx+5,cy+7);x.closePath();x.stroke();x.fillStyle='#42d9ff';x.font='10px Consolas';state.route.forEach((leg,i)=>{const dx=(leg.pos[0]-state.x)/range*w*.42,dz=(leg.pos[1]-state.z)/range*h*.62;const angle=-state.heading*Math.PI/180,px=cx+dx*Math.cos(angle)-dz*Math.sin(angle),py=cy+dx*Math.sin(angle)+dz*Math.cos(angle);if(px>5&&px<w-5&&py>5&&py<h){x.beginPath();x.arc(px,py,4,0,Math.PI*2);x.strokeStyle=i===state.activeLeg?'#ff4cff':'#42d9ff';x.stroke();x.fillStyle='#42d9ff';x.fillText(leg.name,px+6,py+3)}});x.fillStyle='#71e77b';x.font='bold 11px Consolas';x.fillText(state.ap.lnav?'LNAV ACTIVE':'MAP MODE',8,14);x.fillStyle='#fff';x.fillText(`GS ${Math.round(state.ias)} KT`,8,h-8);x.fillText('RANGE 80',w-65,h-8)}
function drawEICAS(){const{x,w,h}=fitCanvas(ui.eicas);x.fillStyle='#020505';x.fillRect(0,0,w,h);if(!powered()){x.fillStyle='#ff8b25';x.font='11px Consolas';x.fillText('ENG DISPLAY',w/2-38,h/2);return}x.fillStyle='#fff';x.font='10px Consolas';x.fillText('N1',w/2-7,15);state.engines.forEach((base,i)=>{const n=base?Math.min(101,22+state.throttle*.78):0,cx=i?w*.72:w*.28,cy=55,r=27;x.strokeStyle='#55615c';x.lineWidth=4;x.beginPath();x.arc(cx,cy,r,.7*Math.PI,2.3*Math.PI);x.stroke();x.strokeStyle=n>95?'#ff4d3d':'#72e57b';x.beginPath();x.arc(cx,cy,r,.7*Math.PI,(.7+1.6*n/100)*Math.PI);x.stroke();x.fillStyle='#fff';x.font='bold 13px Consolas';x.fillText(n.toFixed(1),cx-18,cy+5);x.fillStyle='#72e57b';x.font='10px Consolas';x.fillText(`EGT ${Math.round(n*7.4)}`,cx-23,105)});x.fillStyle='#fff';x.fillText(`FUEL ${Math.round(state.fuel)} KG`,12,h-22);x.fillText(`FLAPS ${state.flaps?['','1','5','15','30','40'][state.flaps]:'UP'}`,12,h-8);x.fillText(`GEAR ${state.gearDown?'DOWN':'UP'}`,w-72,h-8)}
function updateWarnings(){const caution=state.running&&(!powered()||state.engines.some(n=>state.ready&&n<20)||(!state.hydraulics&&state.engines.some(n=>n>50)));$('#masterCaution').classList.toggle('lit',caution);$('#fireWarn').classList.toggle('lit',state.engines.some(n=>n>103))}
function renderView(){const rad=state.heading*Math.PI/180;if(state.external){const behind=new THREE.Vector3(state.x-Math.sin(rad)*55,state.y+24,state.z+Math.cos(rad)*55);camera.position.lerp(behind,.08);camera.lookAt(state.x,state.y,state.z)}else{camera.position.set(state.x,state.y+2.7,state.z-1.8);const look=new THREE.Vector3(state.x+Math.sin(rad)*500,state.y+2.7+Math.tan(state.pitch*Math.PI/180)*500,state.z-Math.cos(rad)*500);camera.up.set(Math.sin(state.roll*Math.PI/180),Math.cos(state.roll*Math.PI/180),0);camera.lookAt(look)}aircraft.visible=state.external;renderer.render(scene,camera)}
function loop(now){requestAnimationFrame(loop);const dt=Math.min(.04,(now-last)/1000);last=now;if(state.running)flightPhysics(dt);state.radioAlt=state.altitude;drawPFD();drawND();drawEICAS();updateWarnings();monitorTutorial();renderView()}requestAnimationFrame(loop);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});refreshChecklist();
